"""ToolPrune: hierarchical tool retrieval POC."""
"""Normalize scraped LiveMCPBench files into tool and query records, annotate, store."""

import json
import random
import re
import sqlite3
from collections import defaultdict
from pathlib import Path

TOOL_EFFECT_READ = ("get", "list", "read", "search", "fetch", "query", "find", "view", "check", "lookup", "describe")
TOOL_EFFECT_DESTRUCTIVE = ("delete", "remove", "drop", "kill", "terminate", "destroy", "purge")
DEV_FRACTION = 0.30
SPLIT_SEED = 42


def load_tools(raw_dir: Path) -> list[dict]:
    catalog = json.loads((raw_dir / "tools.json").read_text())
    tools = []
    for entry in catalog:
        for server_key, server in entry.get("tools", {}).items():
            for tool in server.get("tools", []):
                schema = tool.get("inputSchema") or {}
                props = schema.get("properties") or {}
                tools.append({
                    "id": f"{server_key}::{tool['name']}",
                    "server": server_key,
                    "catalog_name": entry.get("name", ""),
                    "catalog_category": entry.get("category", ""),
                    "name": tool["name"],
                    "description": tool.get("description", ""),
                    "input_schema": schema,
                    "param_names": sorted(props.keys()),
                    "required": sorted(schema.get("required") or []),
                })
    ids = [t["id"] for t in tools]
    if len(ids) != len(set(ids)):
        raise ValueError("duplicate tool ids after normalization")
    return tools


def _name_variants(name: str) -> list[str]:
    return [name, name.replace("-", "_"), name.replace("_", "-")]


def _resolve(name: str, by_name: dict[str, list[dict]]) -> list[dict]:
    seen, hits = set(), []
    for variant in _name_variants(name.strip()):
        for tool in by_name.get(variant, []):
            if tool["id"] not in seen:
                seen.add(tool["id"])
                hits.append(tool)
    return hits


def load_queries(raw_dir: Path, tools: list[dict]) -> list[dict]:
    tasks = json.loads((raw_dir / "tasks.json").read_text())
    by_name: dict[str, list[dict]] = defaultdict(list)
    for tool in tools:
        by_name[tool["name"]].append(tool)

    queries = []
    for task in tasks:
        meta = task.get("Annotator Metadata") or {}
        raw_names = [re.sub(r"^\s*\d+\.\s*", "", line).strip()
                     for line in (meta.get("Tools") or "").splitlines() if line.strip()]
        gold, unresolved, ambiguous = [], [], []
        for name in raw_names:
            hits = _resolve(name, by_name)
            if not hits:
                unresolved.append(name)
            elif len(hits) == 1:
                gold.append(hits[0]["id"])
            else:
                ambiguous.append([h["id"] for h in hits])
        queries.append({
            "id": task["task_id"],
            "text": task["Question"],
            "category": task.get("category", ""),
            "answer": task.get("answers", ""),
            "steps": meta.get("Steps", ""),
            "gold_names": raw_names,
            "gold_tools": gold,
            "ambiguous_gold": ambiguous,
            "unresolved_gold": unresolved,
            "type": "multi_tool" if len(gold) > 1 else "domain",
        })
    return queries


def annotate_tools(tools: list[dict]) -> None:
    for tool in tools:
        verb = re.split(r"[_\-\s]", tool["name"].lower())[0]
        if verb in TOOL_EFFECT_READ:
            effect = "read"
        elif verb in TOOL_EFFECT_DESTRUCTIVE:
            effect = "destructive"
        else:
            effect = "write"
        tool["effect"] = effect
        tool["effect_source"] = "heuristic:name-verb"


def annotate_queries(queries: list[dict], tools: list[dict]) -> None:
    by_id = {t["id"]: t for t in tools}
    by_name: dict[str, list[str]] = defaultdict(list)
    for tool in tools:
        by_name[tool["name"]].append(tool["id"])

    for q in queries:
        gold = set(q["gold_tools"])
        # Confusers: non-gold tools sharing an exact name with a gold tool (collision set).
        confusers = set()
        for tid in q["gold_tools"]:
            for other in by_name[by_id[tid]["name"]]:
                if other not in gold:
                    confusers.add(other)
        q["confusers"] = sorted(confusers)
        q["collision"] = bool(confusers)

    ordered = sorted(q["id"] for q in queries)
    rng = random.Random(SPLIT_SEED)
    rng.shuffle(ordered)
    dev_ids = set(ordered[: round(len(ordered) * DEV_FRACTION)])
    for q in queries:
        q["split"] = "dev" if q["id"] in dev_ids else "test"


SCHEMA = """
DROP TABLE IF EXISTS tools;
DROP TABLE IF EXISTS queries;
DROP TABLE IF EXISTS query_tools;
CREATE TABLE tools (
    id TEXT PRIMARY KEY, server TEXT, catalog_name TEXT, catalog_category TEXT,
    name TEXT, description TEXT, input_schema TEXT, param_names TEXT, required TEXT,
    effect TEXT, effect_source TEXT
);
CREATE TABLE queries (
    id TEXT PRIMARY KEY, text TEXT, category TEXT, answer TEXT, steps TEXT,
    gold_names TEXT, gold_tools TEXT, ambiguous_gold TEXT, unresolved_gold TEXT,
    type TEXT, confusers TEXT, collision INTEGER, split TEXT
);
CREATE TABLE query_tools (
    query_id TEXT, tool_id TEXT, role TEXT,
    PRIMARY KEY (query_id, tool_id, role)
);
"""


def store(db_path: Path, out_dir: Path, tools: list[dict], queries: list[dict]) -> None:
    db_path.parent.mkdir(parents=True, exist_ok=True)
    out_dir.mkdir(parents=True, exist_ok=True)
    with sqlite3.connect(db_path) as con:
        con.executescript(SCHEMA)
        con.executemany(
            "INSERT INTO tools VALUES (?,?,?,?,?,?,?,?,?,?,?)",
            [(t["id"], t["server"], t["catalog_name"], t["catalog_category"], t["name"],
              t["description"], json.dumps(t["input_schema"]), json.dumps(t["param_names"]),
              json.dumps(t["required"]), t["effect"], t["effect_source"]) for t in tools],
        )
        con.executemany(
            "INSERT INTO queries VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",
            [(q["id"], q["text"], q["category"], q["answer"], q["steps"],
              json.dumps(q["gold_names"]), json.dumps(q["gold_tools"]),
              json.dumps(q["ambiguous_gold"]), json.dumps(q["unresolved_gold"]),
              q["type"], json.dumps(q["confusers"]), int(q["collision"]), q["split"]) for q in queries],
        )
        con.executemany(
            "INSERT OR IGNORE INTO query_tools VALUES (?,?,?)",
            [(q["id"], tid, "gold") for q in queries for tid in q["gold_tools"]]
            + [(q["id"], tid, "confuser") for q in queries for tid in q["confusers"]],
        )
        con.commit()

    with (out_dir / "tools.jsonl").open("w") as f:
        for t in tools:
            f.write(json.dumps(t, ensure_ascii=False) + "\n")
    with (out_dir / "queries.jsonl").open("w") as f:
        for q in queries:
            f.write(json.dumps(q, ensure_ascii=False) + "\n")
"""Scrape LiveMCPBench raw files from Hugging Face into data/raw and record a manifest."""

import hashlib
import json
from datetime import datetime, timezone
from pathlib import Path

import httpx

BASE = "https://huggingface.co/datasets/ICIP/LiveMCPBench/resolve/main"
FILES = {
    "tools.json": f"{BASE}/tools/tools.json",
    "all_config.json": f"{BASE}/tools/all_config.json",
    "tasks.json": f"{BASE}/tasks/tasks.json",
}


def fetch_raw(raw_dir: Path, force: bool = False) -> dict:
    raw_dir.mkdir(parents=True, exist_ok=True)
    manifest = {}
    with httpx.Client(follow_redirects=True, timeout=120) as client:
        for name, url in FILES.items():
            target = raw_dir / name
            if force or not target.exists():
                resp = client.get(url)
                resp.raise_for_status()
                target.write_bytes(resp.content)
            data = target.read_bytes()
            manifest[name] = {
                "url": url,
                "bytes": len(data),
                "sha256": hashlib.sha256(data).hexdigest(),
                "fetched_at": datetime.now(timezone.utc).isoformat(),
            }
    (raw_dir / "manifest.json").write_text(json.dumps(manifest, indent=2))
    return manifest
"""Build the POC dataset: scrape -> normalize -> annotate -> store -> BM25 gate.

Run: python -m toolprune.pipeline
Neatlogs spans are recorded locally; they export only when NEATLOGS_API_KEY is set.
"""

import json
import math
import os
import re
from collections import Counter
from pathlib import Path

import neatlogs

from toolprune import dataset, fetch

ROOT = Path(__file__).resolve().parents[2]
RAW_DIR = ROOT / "data" / "raw"
POC_DIR = ROOT / "data" / "poc"
DB_PATH = ROOT / "data" / "poc.sqlite"
GATE_TARGET = 31.68  # BM25 Recall@5 on LiveMCPBench, from the toolrank README (self-reported)
GATE_TOLERANCE = 2.0


def _tokens(text: str) -> list[str]:
    return re.findall(r"[a-z0-9]+", text.lower())


def bm25_recall_at_5(tools: list[dict], queries: list[dict], k1: float = 1.5, b: float = 0.75) -> float:
    docs = [_tokens(f"{t['name']} {t['name']} {t['description']} {t['server']}") for t in tools]
    avgdl = sum(len(d) for d in docs) / len(docs)
    df: Counter = Counter()
    for d in docs:
        df.update(set(d))
    n = len(docs)
    idf = {w: math.log(1 + (n - c + 0.5) / (c + 0.5)) for w, c in df.items()}
    tf_maps = [Counter(d) for d in docs]
    ids = [t["id"] for t in tools]

    scored_queries = [q for q in queries if q["gold_tools"]]
    total = 0.0
    for q in scored_queries:
        qtoks = set(_tokens(q["text"]))
        scores = []
        for i, tf in enumerate(tf_maps):
            dl = len(docs[i])
            s = 0.0
            for w in qtoks:
                if w in tf:
                    f = tf[w]
                    s += idf[w] * f * (k1 + 1) / (f + k1 * (1 - b + b * dl / avgdl))
            scores.append(s)
        top5 = {ids[i] for i in sorted(range(n), key=lambda i: -scores[i])[:5]}
        gold = set(q["gold_tools"])
        total += len(gold & top5) / len(gold)
    return 100.0 * total / len(scored_queries)


def main() -> None:
    neatlogs.init(
        workflow_name="tool-retrieval-eval",
        disable_export=not os.environ.get("NEATLOGS_API_KEY"),
    )

    @neatlogs.span(kind="TOOL", name="tool-fetch")
    def scrape():
        return fetch.fetch_raw(RAW_DIR)

    @neatlogs.span(kind="TOOL", name="tool-normalize")
    def normalize():
        tools = dataset.load_tools(RAW_DIR)
        queries = dataset.load_queries(RAW_DIR, tools)
        return tools, queries

    @neatlogs.span(kind="TOOL", name="tool-enrich")
    def enrich(tools, queries):
        dataset.annotate_tools(tools)
        dataset.annotate_queries(queries, tools)
        return tools, queries

    @neatlogs.span(kind="TOOL", name="tool-store")
    def persist(tools, queries):
        dataset.store(DB_PATH, POC_DIR, tools, queries)

    @neatlogs.span(kind="TOOL", name="tool-gate-bm25")
    def gate(tools, queries):
        return bm25_recall_at_5(tools, queries)

    manifest = scrape()
    tools, queries = normalize()
    tools, queries = enrich(tools, queries)
    persist(tools, queries)
    recall5 = gate(tools, queries)

    (POC_DIR / "stats.json").write_text(json.dumps({
        "servers": len({t["server"] for t in tools}),
        "tools": len(tools),
        "queries": len(queries),
        "queries_by_split": dict(Counter(q["split"] for q in queries)),
        "queries_by_type": dict(Counter(q["type"] for q in queries)),
        "queries_with_confusers": sum(q["collision"] for q in queries),
        "tools_by_effect": dict(Counter(t["effect"] for t in tools)),
        "unresolved_gold_names": sum(len(q["unresolved_gold"]) for q in queries),
        "ambiguous_gold_names": sum(len(q["ambiguous_gold"]) for q in queries),
        "bm25_recall_at_5": round(recall5, 2),
        "gate_target": GATE_TARGET,
        "gate_pass": abs(recall5 - GATE_TARGET) <= GATE_TOLERANCE,
        "sources": manifest,
    }, indent=2))
    neatlogs.flush()
    print(json.dumps(json.loads((POC_DIR / "stats.json").read_text()), indent=2))


if __name__ == "__main__":
    main()
